CREATE TABLE "beans" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "roaster" TEXT NOT NULL DEFAULT '', "origin" TEXT NOT NULL DEFAULT '', "roast_level" TEXT NOT NULL DEFAULT 'medium', "roast_date" INTEGER NULL, "package_g" REAL NULL, "remaining_g" REAL NULL, "archived" INTEGER NOT NULL DEFAULT 0 CHECK ("archived" IN (0, 1)), "created_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "brews" ("id" TEXT NOT NULL, "brewed_at" INTEGER NOT NULL, "recipe_id" TEXT NOT NULL, "lineage_id" TEXT NOT NULL, "method_id" TEXT NOT NULL, "recipe_json" TEXT NOT NULL, "bean_id" TEXT NULL, "equipment_json" TEXT NOT NULL DEFAULT '{}', "actual_time_s" INTEGER NULL, "assessment_json" TEXT NULL, "score" INTEGER NULL, "correction_json" TEXT NULL, "correction_accepted" INTEGER NOT NULL DEFAULT 0 CHECK ("correction_accepted" IN (0, 1)), "notes" TEXT NOT NULL DEFAULT '', "manual" INTEGER NOT NULL DEFAULT 0 CHECK ("manual" IN (0, 1)), PRIMARY KEY ("id"));
CREATE TABLE "event_log" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "at" INTEGER NOT NULL, "type" TEXT NOT NULL, "payload" TEXT NOT NULL DEFAULT '{}');
CREATE TABLE "favorites" ("recipe_id" TEXT NOT NULL, PRIMARY KEY ("recipe_id"));
CREATE TABLE "kv_entries" ("key" TEXT NOT NULL, "value" TEXT NOT NULL, PRIMARY KEY ("key"));
CREATE TABLE "user_recipes" ("id" TEXT NOT NULL, "method_id" TEXT NOT NULL, "json" TEXT NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
